   "questionnaire": {
    "id": "klarbefund-anamnesis",
    "title": "Anamnesis from my own data",
    "version": "2026-11-15"
   },
   "rules": [
    {
     "groups": [
      "ldl",
      "apob",
      "non-hdl",
      "total-chol"
     ],
     "id": "lipids",
     "ifMissing": {
      "apob": "ApoB, the better single measure when triglycerides are high (ESC/EAS 2019)",
      "cac": "A coronary calcium score (CT, no contrast), if the decision about lipid-lowering treatment is still open: it can move the risk up or down (ESC 2021 prevention, class IIb)",
      "lpa": "Lp(a), once in every adult's life (ESC/EAS 2025)"
     },
     "questions": [
      "lipid-medication",
      "diet-fat",
      "family-lipids",
      "family-cvd"
     ],
     "risks": [
      "cardiovascular"
     ],
     "title": "LDL cholesterol or ApoB above the guideline",
     "when": [
      "high"
     ],
     "why": "LDL cholesterol causes atherosclerosis and ApoB counts its particles; how far to lower them depends on the whole risk (ESC/EAS 2019 and the 2025 focused update)."
    },
    {
     "groups": [
      "lpa"
     ],
     "id": "lpa",
     "questions": [
      "family-cvd",
      "family-lipids",
      "relatives-lpa"
     ],
     "risks": [
      "cardiovascular"
     ],
     "tests": [
      "Lp(a) for parents, siblings and children: it is inherited, one measurement each is enough (EAS consensus 2022)"
     ],
     "title": "Lp(a) raised or above the lab's limit",
     "when": [
      "high",
      "at_limit",
      "lab_high"
     ],
     "why": "Lp(a) is mostly inherited and changes little over life; raised Lp(a) adds to the risk from LDL, and close relatives should be tested (ESC/EAS 2025; EAS consensus 2022)."
    },
    {
     "groups": [
      "tg"
     ],
     "id": "triglycerides",
     "questions": [
      "sample-fasting",
      "alcohol",
      "sugary-drinks"
     ],
     "risks": [
      "cardiovascular",
      "diabetes",
      "liver"
     ],
     "title": "Triglycerides above the guideline",
     "when": [
      "high",
      "at_limit"
     ],
     "why": "Triglycerides rise after a meal, with alcohol and sugar, and with insulin resistance."
    },
    {
     "groups": [
      "ntprobnp"
     ],
     "id": "ntprobnp",
     "questions": [
      "cardiac-symptoms",
      "exercise-before-sample"
     ],
     "risks": [
      "cardiovascular"
     ],
     "tests": [
      "An echocardiogram if there are symptoms (ESC 2021 heart failure guideline)"
     ],
     "title": "NT-proBNP at or above the limit",
     "when": [
      "high",
      "at_limit",
      "lab_high"
     ],
     "why": "NT-proBNP rises when the heart is under strain, but also for a day or two after hard endurance exercise and when the kidneys filter less; below 125 ng/L makes heart failure unlikely (ESC 2021)."
    },
    {
     "groups": [
      "hba1c",
      "glucose"
     ],
     "id": "glucose",
     "questions": [
      "family-diabetes",
      "sugary-drinks",
      "sample-fasting",
      "sleep-apnoea"
     ],
     "risks": [
      "diabetes"
     ],
     "title": "Blood sugar at or above the limit",
     "when": [
      "high",
